// ---- src/shared/json-repair.js
// Tolerant JSON extraction for LLM output.
// The Claude call uses structured outputs, so the happy path is a plain
// JSON.parse. The repair steps exist for the cases that still happen in real
// life: a local Ollama model wrapping JSON in ```fences```, a chatty preface,
// smart quotes, or trailing commas.

const REPAIRS = [
  ['strip-code-fence', (t) => {
    const m = t.match(/```(?:json|JSON)?\s*([\s\S]*?)```/);
    return m ? m[1] : t;
  }],
  ['slice-outer-object', (t) => {
    const start = t.indexOf('{');
    const end = t.lastIndexOf('}');
    return start !== -1 && end > start ? t.slice(start, end + 1) : t;
  }],
  ['normalize-smart-quotes', (t) => t.replace(/[“”„‟]/g, '"').replace(/[‘’]/g, "'")],
  ['remove-trailing-commas', (t) => t.replace(/,\s*([}\]])/g, '$1')],
];

/**
 * Parse JSON from model text. Returns { value, repairs } where `repairs`
 * lists the repair steps that were needed (empty on a clean parse).
 * Throws an Error with a short explanation if nothing works.
 */
function extractJson(text) {
  if (typeof text !== 'string' || text.trim() === '') {
    throw new Error('Model returned no text to parse as JSON');
  }
  let candidate = text.trim();
  try {
    return { value: JSON.parse(candidate), repairs: [] };
  } catch {
    // fall through to repairs
  }
  const applied = [];
  for (const [name, fn] of REPAIRS) {
    const next = fn(candidate);
    if (next !== candidate) {
      applied.push(name);
      candidate = next.trim();
    }
    try {
      return { value: JSON.parse(candidate), repairs: applied };
    } catch {
      // keep going
    }
  }
  const preview = text.slice(0, 120).replace(/\s+/g, ' ');
  throw new Error(`Could not parse model output as JSON after repairs [${applied.join(', ') || 'none'}]: "${preview}..."`);
}

// ---- src/shared/llm-response.js
// Read the text out of an LLM HTTP response, for either provider.
//
// Anthropic Messages API: content is an array of blocks. With adaptive
// thinking on, `thinking` blocks can come before the `text` block, and with
// server-side fallbacks a `fallback` block marks a model switch - so we never
// assume content[0] is the answer. stop_reason must be checked before the
// content is trusted.
//
// Ollama /api/chat (stream: false): { message: { content }, done_reason }.

/**
 * @returns {{ ok: true, text: string, provider: string, model: string|null, fellBack: boolean }
 *         | { ok: false, error: string, provider: string, retryable: boolean }}
 */
function readLlmText(response) {
  if (!response || typeof response !== 'object') {
    return { ok: false, provider: 'unknown', error: 'Empty response from LLM', retryable: true };
  }
  // n8n HTTP node with "continue" error handling puts failures under `error`.
  if (response.error && !response.content && !response.message) {
    const msg = typeof response.error === 'string' ? response.error : response.error.message || JSON.stringify(response.error);
    return { ok: false, provider: 'unknown', error: `LLM request failed: ${msg}`, retryable: true };
  }

  if (Array.isArray(response.content)) {
    const provider = 'anthropic';
    if (response.type === 'error') {
      return { ok: false, provider, error: `Anthropic error: ${response.error?.message || 'unknown'}`, retryable: false };
    }
    if (response.stop_reason === 'refusal') {
      const category = response.stop_details?.category || 'unspecified';
      return { ok: false, provider, error: `Claude declined the request (category: ${category})`, retryable: false };
    }
    if (response.stop_reason === 'max_tokens') {
      return { ok: false, provider, error: 'Claude hit max_tokens - output is incomplete. Raise maxOutputTokens in the Config node.', retryable: false };
    }
    const text = response.content
      .filter((b) => b && b.type === 'text' && typeof b.text === 'string')
      .map((b) => b.text)
      .join('');
    if (!text.trim()) {
      return { ok: false, provider, error: 'Claude returned no text block', retryable: true };
    }
    const fellBack = response.content.some((b) => b && b.type === 'fallback');
    return { ok: true, provider, text, model: response.model || null, fellBack };
  }

  if (response.message && typeof response.message.content === 'string') {
    const provider = 'ollama';
    if (response.done_reason === 'length') {
      return { ok: false, provider, error: 'Ollama stopped at num_predict - output is incomplete', retryable: false };
    }
    const text = response.message.content;
    if (!text.trim()) return { ok: false, provider, error: 'Ollama returned an empty message', retryable: true };
    return { ok: true, provider, text, model: response.model || null, fellBack: false };
  }

  return { ok: false, provider: 'unknown', error: 'Unrecognised LLM response shape', retryable: false };
}

// ---- src/meeting/validate-notes.js
// Validate (and gently repair) the meeting notes object before anything is
// written to Notion. Hard problems go to `errors` (the run alerts instead of
// writing garbage); soft problems go to `warnings` (written to the page).

const PRIORITIES = new Set(['high', 'normal', 'low']);

function stringList(value, field, warnings) {
  if (value === undefined || value === null) return [];
  if (!Array.isArray(value)) {
    warnings.push(`${field} was not a list and was ignored`);
    return [];
  }
  const seen = new Set();
  return value.map(cleanText).filter((s) => s && !seen.has(s.toLowerCase()) && seen.add(s.toLowerCase()));
}

function matchOwner(owner, attendees) {
  const name = cleanText(owner);
  if (!name || /^(unassigned|none|n\/a|unknown|tbd)$/i.test(name)) return 'Unassigned';
  const exact = attendees.find((a) => a.toLowerCase() === name.toLowerCase());
  if (exact) return exact;
  const first = attendees.find((a) => a.split(' ')[0].toLowerCase() === name.split(' ')[0].toLowerCase());
  return first || name;
}

/**
 * @param {unknown} raw          parsed JSON from the model
 * @param {object}  ctx
 * @param {string}  ctx.meetingDate  YYYY-MM-DD
 * @param {string[]} ctx.attendees
 */
function validateMeetingNotes(raw, { meetingDate, attendees = [] } = {}) {
  const errors = [];
  const warnings = [];
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
    return { ok: false, errors: ['Notes are not a JSON object'], warnings, notes: null };
  }

  const summary = cleanText(raw.summary);
  if (!summary) errors.push('summary is missing');
  if (!Array.isArray(raw.actionItems)) errors.push('actionItems must be a list');

  const seenTasks = new Set();
  const actionItems = (Array.isArray(raw.actionItems) ? raw.actionItems : [])
    .map((item, i) => {
      const task = cleanText(item?.task);
      if (!task) {
        warnings.push(`action item #${i + 1} had no task text and was dropped`);
        return null;
      }
      const key = task.toLowerCase();
      if (seenTasks.has(key)) {
        warnings.push(`duplicate action item dropped: "${clip(task, 60)}"`);
        return null;
      }
      seenTasks.add(key);

      let dueDate = item.dueDate ?? null;
      if (dueDate !== null && !isValidIsoDate(dueDate)) {
        warnings.push(`"${clip(task, 60)}": invalid due date "${dueDate}" removed`);
        dueDate = null;
      } else if (dueDate && meetingDate && dueDate < meetingDate) {
        warnings.push(`"${clip(task, 60)}": due date ${dueDate} is before the meeting and was removed`);
