function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

/**
 * Cut text to `max` characters on a word boundary and say so, instead of
 * cutting silently. Used only for display surfaces with hard limits
 * (Notion text blocks, Telegram messages) - never for LLM input.
 */
function clip(value, max, notice = ' [...truncated]') {
  const text = String(value ?? '');
  if (text.length <= max) return text;
  const room = Math.max(0, max - notice.length);
  const cut = text.slice(0, room);
  const lastSpace = cut.lastIndexOf(' ');
  return (lastSpace > room * 0.6 ? cut.slice(0, lastSpace) : cut) + notice;
}

/** 32-bit FNV-1a hash as 8 hex chars. Deterministic, no crypto module needed. */
function fnv1a(input, seed = 0x811c9dc5) {
  let hash = seed >>> 0;
  const str = String(input);
  for (let i = 0; i < str.length; i++) {
    hash ^= str.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash.toString(16).padStart(8, '0');
}

/**
 * Deterministic UUID-shaped id (Qdrant accepts UUID strings as point ids).
 * Not RFC-4122 random - it is a stable fingerprint so re-ingesting the same
 * chunk overwrites the same point instead of duplicating it.
 */
function stableUuid(input) {
  const h = [0x811c9dc5, 0x01000193, 0x9e3779b9, 0x85ebca6b].map((seed) => fnv1a(input, seed)).join('');
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-5${h.slice(13, 16)}-a${h.slice(17, 20)}-${h.slice(20, 32)}`;
}

/** YYYY-MM-DD for a Date in the given IANA timezone. */
function isoDateInZone(date, timeZone) {
  return new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(date);
}

/** True for a real calendar date in YYYY-MM-DD form (rejects 2026-02-30). */
function isValidIsoDate(value) {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [y, m, d] = value.split('-').map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  return dt.getUTCFullYear() === y && dt.getUTCMonth() === m - 1 && dt.getUTCDate() === d;
}

// ---- src/shared/redact.js
// Scrub things that look like credentials before text leaves n8n
// (alerts, log files). Error messages from HTTP nodes sometimes echo headers.

const PATTERNS = [
  [/sk-ant-[A-Za-z0-9_-]{10,}/g, 'sk-ant-***'],
  [/\bsk-[A-Za-z0-9_-]{20,}/g, 'sk-***'],
  [/\b(?:secret|ntn)_[A-Za-z0-9]{20,}/g, '***notion-token***'],
  [/\b\d{8,10}:[A-Za-z0-9_-]{35}\b/g, '***telegram-bot-token***'],
  [/\bya29\.[A-Za-z0-9._-]{20,}/g, '***google-oauth-token***'],
  [/\b(Bearer|Basic)\s+[A-Za-z0-9._~+/=-]{12,}/gi, '$1 ***'],
  [/\b(x-api-key|api[_-]?key|authorization|password|passwd|token)(["']?\s*[:=]\s*["']?)[^\s"',}]+/gi, '$1$2***'],
  [/eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}/g, '***jwt***'],
];

function redactSecrets(value) {
  let text = String(value ?? '');
  for (const [re, replacement] of PATTERNS) text = text.replace(re, replacement);
  return text;
}

// ---- src/shared/alert.js
/**
 * Build a human-readable alert for Telegram (HTML) and email (plain text).
 * Written for a non-technical household member: what broke, whether anything
 * was lost, and what to do next.
 */
function buildAlert({ workflow, stage, message, details = {}, executionUrl = null, hint = null }) {
  const safeMessage = redactSecrets(message || 'Unknown error');
  const lines = Object.entries(details)
    .filter(([, v]) => v !== undefined && v !== null && v !== '')
    .map(([k, v]) => [k, redactSecrets(typeof v === 'string' ? v : JSON.stringify(v))]);

  const html = [
    `<b>Home automation: ${escapeHtml(workflow)} needs attention</b>`,
    `Step: <code>${escapeHtml(stage)}</code>`,
    `Problem: ${escapeHtml(clip(safeMessage, 800))}`,
    ...lines.map(([k, v]) => `${escapeHtml(k)}: ${escapeHtml(clip(v, 300))}`),
    hint ? `\nWhat to do: ${escapeHtml(hint)}` : '',
    executionUrl ? `\n<a href="${escapeHtml(executionUrl)}">Open the run in n8n</a>` : '',
  ].filter(Boolean).join('\n');

  const text = [
    `${workflow} needs attention`,
    `Step: ${stage}`,
    `Problem: ${safeMessage}`,
    ...lines.map(([k, v]) => `${k}: ${v}`),
    hint ? `What to do: ${hint}` : '',
    executionUrl ? `Run details: ${executionUrl}` : '',
    '',
    'See docs/runbook.md -> "When something fails".',
  ].filter((l) => l !== '').join('\n');

  return {
    telegramHtml: clip(html, 4000),
    emailSubject: `[home-n8n] ${workflow}: ${stage} failed`,
    emailText: text,
  };
}

// ---- n8n entry point

const config = $('Config').first().json;
const runUrl = config.n8nBaseUrl ? `${config.n8nBaseUrl.replace(/\/$/, '')}/workflow/${$workflow.id}/executions/${$execution.id}` : null;
return $input.all().map((item) => {
  const j = item.json;
  const fromRetry = Boolean(j.retry);
  return {
    json: {
      chatId: config.telegramChatId,
      alertEmail: config.alertEmail,
      ...buildAlert({
        workflow: $workflow.name,
        stage: fromRetry ? 'Claude API call' : j.stage || 'unknown step',
        message: fromRetry ? j.retry.reason : j.error,
        details: { Meeting: j.meeting?.title, Source: j.meeting?.source },
        executionUrl: runUrl,
        hint: fromRetry
          ? 'Nothing was lost - the transcript is stored in this n8n run. Retry the execution once the API is healthy.'
          : 'Open the run in n8n to see the Claude output; the transcript is stored there.',
      }),
    },
  };
});
